    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We penalize very small residuals (e.g., < 5) late in the stream as they become "dead" space.
    let mut score = post * (1.0 + 0.5 * (1.0 - progress));

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality is poor across all bins.
        // We add a dynamic threshold based on progress and remaining space.
        score = 25.0 + (progress * 50.0);
    } else {
        // Lookahead heuristic: If the next item exists, penalize residuals that are too 
        // small to fit the next item, but only if we are not near the end of the stream.
        if next_item_size > 0 && post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }

        // Encourage consolidation: If few bins fit the current item, prioritize 
        // filling the most restricted ones (lower fitting_bins_count).
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Adjust based on mean_residual to keep bins balanced.
    // If this bin is emptier than the average, it's a better candidate to fill.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We want to minimize the post-residual (Best Fit principle),
    // but we add penalties for creating "dead space" that is too small for common items.
    let mut score = post;

    // Penalty: If post_residual is small (e.g., < 15), it creates "fragmentation".
    // We scale this penalty by progress: as the stream ends, we care less about fragmentation.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: If the next item is large, prioritize bins that keep 
    // enough space to accommodate it or minimize the waste if it won't fit anyway.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly (Best Fit for lookahead)
            score -= (bin_capacity as f64 - post - next_item_size as f64).abs() * 0.5;
        } else {
            // Penalize bins that are "almost" large enough for the next item but fail
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // New bin logic: 
    // If this is a new bin (bin_residual == bin_capacity), calculate a "threshold" 
    // to open it based on how well the item fits in existing bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, decreasing as we run out of open bins
        score += (100.0 - (open_bins_count as f64 * 5.0)) * (1.0 - progress);
    } else {
        // If this is an existing bin, reward it if it's the only one that fits the item
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Coupling with mean_residual:
    // Avoid bins that deviate significantly from the mean efficiency
    score += (post - mean_residual).powi(2) * 0.01;

    score
}

