    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "fragmented" space (too small for most items)
    // We heavily penalize residuals that are small but not zero.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that can fit the future item
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 15.0; // Penalize bins that will "block" the next item
        }
    }

    // Global state awareness:
    // If we have many open bins, we prioritize closing/filling existing ones.
    // If open_bins_count is low, we are more flexible.
    score += (open_bins_count as f64) * 2.0;

    // Favor bins that are closer to the mean residual to keep bin usage uniform,
    // unless the bin is nearly full, in which case we prioritize finishing it.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Heuristic for New Bin (bin_residual == bin_capacity):
    // Only open a new bin if the best available fit is very poor (e.g., leaving 
    // a tiny, unusable gap) or if we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Mandatory
        } else {
            // High base cost to open a new bin, weighted by progress
            score = 65.0 - (progress * 10.0);
        }
    } else if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        // If this is the ONLY bin that fits and it leaves a bad gap, 
        // consider the new bin option instead.
        score += 20.0;
    }

    score
}

